1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Trove — Bookmark prototype</title>
7	  <style>
8	    :root {
9	      --paper: #f7f5ef;
10	      --ink: #202621;
11	      --muted: #6d756e;
12	      --line: #dedfd8;
13	      --green: #245943;
14	      --green-hover: #184a36;
15	      --white: #fff;
16	      --shadow: 0 18px 50px rgba(32, 38, 33, .1);
17	    }
18	
19	    * { box-sizing: border-box; }
20	    body {
21	      margin: 0;
22	      min-width: 880px;
23	      color: var(--ink);
24	      background: var(--paper);
25	      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
26	    }
27	
28	    button, input { font: inherit; }
29	    button { cursor: pointer; }
30	
31	    .app { display: grid; min-height: 100vh; grid-template-columns: 250px 1fr; }
32	    .sidebar {
33	      display: flex;
34	      flex-direction: column;
35	      padding: 32px 24px 24px;
36	      border-right: 1px solid var(--line);
37	      background: rgba(255, 255, 255, .42);
38	    }
39	    .brand { display: flex; align-items: center; gap: 11px; margin-bottom: 46px; font-weight: 760; font-size: 21px; letter-spacing: -.02em; }
40	    .brand-mark { display: grid; place-items: center; width: 34px; height: 34px; color: var(--white); background: var(--green); border-radius: 10px; font-family: Georgia, serif; font-size: 22px; }
41	    .nav-title { margin: 0 0 10px 12px; color: #8a918b; font-size: 11px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; }
42	    .nav { display: grid; gap: 5px; }
43	    .nav-item { display: flex; align-items: center; gap: 12px; padding: 11px 12px; border-radius: 10px; color: var(--muted); font-size: 14px; }
44	    .nav-item.active { color: var(--ink); background: #e8ebe4; font-weight: 650; }
45	    .nav-item svg { width: 18px; height: 18px; }
46	    .future { margin-top: 25px; opacity: .55; }
47	    .sidebar-note { margin-top: auto; color: #969c97; font-size: 12px; line-height: 1.45; }
48	
49	    main { padding: 44px 6vw; }
50	    .topbar { display: flex; align-items: center; justify-content: space-between; gap: 24px; }
51	    h1 { margin: 0; font-family: Georgia, "Times New Roman", serif; font-size: 38px; font-weight: 500; letter-spacing: -.025em; }
52	    .subhead { margin: 8px 0 0; color: var(--muted); font-size: 14px; }
53	    .add-button { display: inline-flex; align-items: center; gap: 9px; min-height: 44px; padding: 0 18px; border: 0; border-radius: 12px; color: var(--white); background: var(--green); font-weight: 700; box-shadow: 0 6px 16px rgba(36, 89, 67, .18); }
54	    .add-button:hover { background: var(--green-hover); }
55	    .add-button span { font-size: 21px; font-weight: 400; line-height: 1; }
56	
57	    .content { margin-top: 46px; }
58	    .empty {
59	      display: grid;
60	      place-items: center;
61	      min-height: 450px;
62	      padding: 60px;
63	      border: 1px dashed #cfd3cb;
64	      border-radius: 24px;
65	      background: rgba(255,255,255,.24);
66	      text-align: center;
67	    }
68	    .empty-icon { display: grid; place-items: center; width: 74px; height: 74px; margin: 0 auto 20px; border-radius: 22px; color: var(--green); background: #e6ece6; }
69	    .empty h2 { margin: 0 0 9px; font-family: Georgia, serif; font-size: 25px; font-weight: 500; }
70	    .empty p { max-width: 400px; margin: 0 auto 24px; color: var(--muted); font-size: 14px; line-height: 1.55; }
71	
72	    .bookmark-list { display: none; }
73	    .bookmark-list.visible { display: block; }
74	    .list-heading { margin: 0 0 14px; color: var(--muted); font-size: 12px; font-weight: 750; letter-spacing: .08em; text-transform: uppercase; }
75	    .card {
76	      display: grid;
77	      grid-template-columns: 48px minmax(0, 1fr) auto;
78	      align-items: center;
79	      gap: 17px;
80	      padding: 19px 20px;
81	      color: inherit;
82	      border: 1px solid var(--line);
83	      border-radius: 16px;
84	      background: rgba(255,255,255,.75);
85	      box-shadow: 0 8px 30px rgba(32, 38, 33, .04);
86	      text-decoration: none;
87	      transition: transform .15s ease, box-shadow .15s ease, border-color .15s ease;
88	    }
89	    .card:hover { transform: translateY(-2px); border-color: #bdc7bd; box-shadow: 0 12px 30px rgba(32, 38, 33, .09); }
90	    .favicon { display: grid; place-items: center; width: 48px; height: 48px; border-radius: 12px; color: #fff; background: #d94836; font-family: Georgia, serif; font-size: 22px; font-weight: bold; }
91	    .card-copy { min-width: 0; }
92	    .card-title { margin: 0 0 5px; font-size: 16px; font-weight: 720; }
93	    .card-description { overflow: hidden; margin: 0 0 7px; color: var(--muted); font-size: 13px; line-height: 1.4; text-overflow: ellipsis; white-space: nowrap; }
94	    .card-domain { color: #8a918b; font-size: 12px; }
95	    .external { color: #899089; }
96	
97	    .overlay { position: fixed; inset: 0; display: none; place-items: center; padding: 24px; background: rgba(25, 31, 26, .45); backdrop-filter: blur(4px); }
98	    .overlay.open { display: grid; }
99	    .dialog { width: min(550px, 100%); padding: 28px; border: 1px solid rgba(255,255,255,.65); border-radius: 22px; background: var(--white); box-shadow: var(--shadow); }
100	    .dialog-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
101	    .dialog h2 { margin: 0 0 8px; font-family: Georgia, serif; font-size: 27px; font-weight: 500; }
102	    .dialog p { margin: 0; color: var(--muted); font-size: 14px; line-height: 1.5; }
103	    .close { display: grid; place-items: center; width: 36px; height: 36px; border: 0; border-radius: 10px; color: #737b74; background: #f2f3ef; font-size: 20px; }
104	    label { display: block; margin: 25px 0 8px; font-size: 13px; font-weight: 700; }
105	    .url-input { width: 100%; height: 48px; padding: 0 14px; border: 1px solid #cdd2cc; border-radius: 11px; outline: none; }
106	    .url-input:focus { border-color: var(--green); box-shadow: 0 0 0 3px rgba(36, 89, 67, .12); }
107	    .error { min-height: 18px; margin: 6px 0 0; color: #a33a2d; font-size: 12px; }
108	    .dialog-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 18px; }
109	    .secondary, .save { min-height: 42px; padding: 0 17px; border-radius: 10px; font-weight: 700; }
110	    .secondary { border: 1px solid var(--line); color: #596159; background: #fff; }
111	    .save { border: 0; color: #fff; background: var(--green); }
112	    .save:disabled { cursor: wait; opacity: .75; }
113	    .save-status { display: none; }
114	    .save.loading .save-label { display: none; }
115	    .save.loading .save-status { display: inline; }
116	    .toast { position: fixed; right: 28px; bottom: 28px; display: none; align-items: center; gap: 10px; padding: 13px 17px; border-radius: 12px; color: #fff; background: #26392f; box-shadow: var(--shadow); font-size: 13px; font-weight: 650; }
117	    .toast.show { display: flex; animation: rise .2s ease-out; }
118	    @keyframes rise { from { opacity: 0; transform: translateY(8px); } }
119	  </style>
120	</head>
121	<body>
122	  <div class="app" data-harness-ready="true">
123	    <aside class="sidebar">
124	      <div class="brand"><span class="brand-mark">T</span> Trove</div>
125	      <p class="nav-title">Library</p>
126	      <nav class="nav" aria-label="Library">
127	        <div class="nav-item active">
128	          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M5 4.5h14v15H5z"/><path d="M8 8h8M8 12h8M8 16h5"/></svg>
129	          All bookmarks
130	        </div>
131	        <div class="future">
132	          <div class="nav-item">
133	            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M7 4h10v16l-5-3-5 3z"/></svg>
134	            Read later
135	          </div>
136	          <div class="nav-item">
137	            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 7h16v13H4zM3 4h18v3H3zM9 11h6"/></svg>
138	            Archive
139	          </div>
140	        </div>
141	      </nav>
142	      <p class="sidebar-note">Personal library<br>No account needed</p>
143	    </aside>
144	
145	    <main>
146	      <header class="topbar">
147	        <div>
148	          <h1>All bookmarks</h1>
149	          <p class="subhead" id="count">Your saved links will live here.</p>
150	        </div>
151	        <button class="add-button" id="addLink" type="button"><span>+</span> Save link</button>
152	      </header>
153	
154	      <section class="content">
155	        <div class="empty" id="emptyState">
156	          <div>
157	            <div class="empty-icon">
158	              <svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M6 3.5h12v17L12 17l-6 3.5z"/><path d="M9 8h6"/></svg>
159	            </div>
160	            <h2>Save your first find</h2>
161	            <p>Paste a web address and Trove will turn it into a bookmark you can recognize later.</p>
162	            <button class="add-button" id="emptyAdd" type="button"><span>+</span> Save a link</button>
163	          </div>
164	        </div>
165	
166	        <div class="bookmark-list" id="bookmarkList">
167	          <p class="list-heading">Recently saved</p>
168	          <a class="card" id="savedCard" href="https://www.seriouseats.com/the-best-roast-potatoes-ever-recipe" target="_blank" rel="noopener">
169	            <div class="favicon">S</div>
170	            <div class="card-copy">
171	              <p class="card-title">The Best Crispy Roast Potatoes Ever</p>
172	              <p class="card-description">These roast potatoes maximize the contrast between crisp, crunchy exteriors and creamy centers.</p>
173	              <span class="card-domain">seriouseats.com</span>
174	            </div>
175	            <svg class="external" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-label="Opens website"><path d="M14 5h5v5M19 5l-8 8"/><path d="M18 13v6H5V6h6"/></svg>
176	          </a>
177	        </div>
178	      </section>
179	    </main>
180	  </div>
181	
182	  <div class="overlay" id="overlay" role="dialog" aria-modal="true" aria-labelledby="dialogTitle">
183	    <form class="dialog" id="saveForm">
184	      <div class="dialog-header">
185	        <div>
186	          <h2 id="dialogTitle">Save a link</h2>
187	          <p>Paste the page address. The title, description, and icon will be filled in for you.</p>
188	        </div>
189	        <button class="close" id="closeDialog" type="button" aria-label="Close">×</button>
190	      </div>
191	      <label for="url">Web address</label>
192	      <input class="url-input" id="url" name="url" type="url" placeholder="https://example.com/article" autocomplete="off" required>
193	      <p class="error" id="error" role="alert"></p>
194	      <div class="dialog-actions">
195	        <button class="secondary" id="cancel" type="button">Cancel</button>
196	        <button class="save" id="save" type="submit"><span class="save-label">Save link</span><span class="save-status">Fetching page details…</span></button>
197	      </div>
198	    </form>
199	  </div>
200	
201	  <div class="toast" id="toast" role="status">✓ Bookmark saved with page details</div>
202	
203	  <script>
204	    const overlay = document.querySelector('#overlay');
205	    const urlInput = document.querySelector('#url');
206	    const saveForm = document.querySelector('#saveForm');
207	    const saveButton = document.querySelector('#save');
208	    const error = document.querySelector('#error');
209	
210	    function openDialog() {
211	      overlay.classList.add('open');
212	      error.textContent = '';
213	      setTimeout(() => urlInput.focus(), 0);
214	    }
215	
216	    function closeDialog() {
217	      overlay.classList.remove('open');
218	      saveForm.reset();
219	      error.textContent = '';
220	    }
221	
222	    document.querySelector('#addLink').addEventListener('click', openDialog);
223	    document.querySelector('#emptyAdd').addEventListener('click', openDialog);
224	    document.querySelector('#closeDialog').addEventListener('click', closeDialog);
225	    document.querySelector('#cancel').addEventListener('click', closeDialog);
226	    overlay.addEventListener('click', event => { if (event.target === overlay) closeDialog(); });
227	
228	    saveForm.addEventListener('submit', event => {
229	      event.preventDefault();
230	      let parsed;
231	      try { parsed = new URL(urlInput.value); } catch { error.textContent = 'Enter a full web address, including https://'; return; }
232	      if (!['http:', 'https:'].includes(parsed.protocol)) { error.textContent = 'Enter a web address that begins with http:// or https://'; return; }
233	      error.textContent = '';
234	      saveButton.disabled = true;
235	      saveButton.classList.add('loading');
236	      setTimeout(() => {
237	        closeDialog();
238	        saveButton.disabled = false;
239	        saveButton.classList.remove('loading');
240	        document.querySelector('#emptyState').style.display = 'none';
241	        document.querySelector('#bookmarkList').classList.add('visible');
242	        document.querySelector('#count').textContent = '1 saved bookmark';
243	        const toast = document.querySelector('#toast');
244	        toast.classList.add('show');
245	        setTimeout(() => toast.classList.remove('show'), 2600);
246	      }, 700);
247	    });
248	  </script>
249	</body>
250	</html>
